module problem_solver (\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] a,\n    input [63:0] s,\n    output reg [31:0] result,\n    output reg done\n);\n\n    parameter N = 16;\n    parameter MAX_SUM = 9*N;\n    localparam TOTAL_SUBSTRINGS = N*(N+1)/2;\n\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] STATE1 = 2'b01;\n    localparam [1:0] STATE2 = 2'b10;\n    localparam [1:0] DONE = 2'b11;\n\n    reg [1:0] state, next_state;\n    reg [4:0] i, j;\n    reg [7:0] current_sum;\n    reg [7:0] freq [0:MAX_SUM];\n    reg [7:0] U;\n\n    wire [3:0] digit [0:N-1];\n    genvar g;\n    generate\n        for (g=0; g<N; g=g+1) begin\n            assign digit[g] = s[4*g +: 4];\n        end\n    endgenerate\n\n    wire [7:0] new_sum = current_sum + digit[j];\n    wire [31:0] quotient = a / U;\n    wire [31:0] remainder = a % U;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) state <= IDLE;\n        else state <= next_state;\n    end\n\n    always @(*) begin\n        case (state)\n            IDLE:   next_state = start ? STATE1 : IDLE;\n            STATE1: next_state = (i < N) ? ((j < N) ? STATE1 : ((i == N-1) ? STATE2 : STATE1)) : STATE2;\n            STATE2: next_state = (a == 0) ? DONE : ((U <= MAX_SUM) ? STATE2 : DONE);\n            DONE:   next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            i <= 5'd0;\n            j <= 5'd0;\n            current_sum <= 8'd0;\n            result <= 32'd0;\n            done <= 1'b0;\n            U <= 8'd0;\n            for (integer k=0; k<=MAX_SUM; k=k+1) begin\n                freq[k] <= 8'd0;\n            end\n        end else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        i <= 5'd0;\n                        j <= 5'd0;\n                        current_sum <= 8'd0;\n                        result <= 32'd0;\n                        U <= 8'd0;\n                        for (integer k=0; k<=MAX_SUM; k=k+1) begin\n                            freq[k] <= 8'd0;\n                        end\n                    end\n                end\n                \n                STATE1: begin\n                    if (i < N) begin\n                        if (j < N) begin\n                            freq[new_sum] <= freq[new_sum] + 8'd1;\n                            current_sum <= new_sum;\n                            j <= j + 5'd1;\n                        end else begin\n                            i <= i + 5'd1;\n                            j <= i + 5'd1;\n                            current_sum <= 8'd0;\n                        end\n                    end\n                end\n                \n                STATE2: begin\n                    if (a == 32'd0) begin\n                        result <= (32'd2 * freq[0] * TOTAL_SUBSTRINGS) - (freq[0] * freq[0]);\n                        done <= 1'b1;\n                    end else if (U <= MAX_SUM) begin\n                        if ((U != 8'd0) && (remainder == 32'd0) && (quotient <= MAX_SUM)) begin\n                            result <= result + (freq[U] * freq[quotient]);\n                        end\n                        U <= U + 8'd1;\n                    end else begin\n                        done <= 1'b1;\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\nendmodule